prelude_js:
// 基线的方差曲线（解析解，score²≡1 时 Var = E[(R−b)²] − 1）：
// R(a1)=100、R(a2)=102、π 各 0.5。b=0 → 10201；b=101（最优）→ 0；
// b=202 → 10201（与 b=0 相同）；b=250 → 22201（2.18×，比不用基线更差）。
function bVar(b){return 0.5*Math.pow(100-b,2)+0.5*Math.pow(102-b,2)-1;}
function occSum(g){return 1/(1-g);}
function cpiPen(g,a){return 2*g*a*a/Math.pow(1-g,2);}

